import re
import json
import logging
import asyncio
import httpx
from dataclasses import dataclass
from time import perf_counter
from typing import List, Dict, Any, Tuple, Optional
from app.config import settings
from app.models import MemoryReceipt, QueryResponse
from app.vault import vault

logger = logging.getLogger(__name__)

# ─── Simulation notice shown only when STRICT_LIVE_MODE is False ─────────────
_SIMULATED_BANNER = (
    "\n\n---\n"
    "⚠️ [SIMULATED — No live Nemotron key] This answer was generated by a "
    "local keyword-matching fallback. Add a valid NEBIUS_API_KEY to .env "
    "and restart the server for live NVIDIA Nemotron inference via Nebius Token Factory."
)

# API call retry settings
_MAX_RETRIES = 2
_RETRY_BACKOFF = 1.5  # seconds


@dataclass
class ModelCallResult:
    text: str
    model: str
    degraded_message: Optional[str] = None
    latency_ms: Optional[int] = None
    input_tokens: Optional[int] = None
    output_tokens: Optional[int] = None


def clean_reasoning_text(text: str) -> str:
    """Strips stray reasoning / thinking blocks from model responses.

    Nemotron Super and reasoning models may include internal reasoning in
    <think>...</think>, <thought>...</thought>, or similar blocks before
    producing the user-facing response.
    """
    if not text:
        return ""
    # Strip <think>...</think> and <thought>...</thought> (multi-line, case-insensitive)
    cleaned = re.sub(r"<(?:think|thought)>[\s\S]*?</(?:think|thought)>", "", text, flags=re.IGNORECASE)
    # Strip unclosed opening tags at the beginning if any (e.g. model ran out of tokens while thinking)
    cleaned = re.sub(r"^<(?:think|thought)>[\s\S]*$", "", cleaned, flags=re.IGNORECASE)
    # If the model emits "Thinking Process:\n...Answer:" pattern
    answer_match = re.search(r"(?:^|\n)(?:###?\s*)?(?:Final\s+)?Answer:\s*([\s\S]*)$", cleaned, flags=re.IGNORECASE)
    if answer_match and ("thinking process" in cleaned.lower() or "thought:" in cleaned.lower()):
        cleaned = answer_match.group(1)
    return cleaned.strip()


def parse_nano_json(raw: str) -> List[Dict[str, Any]]:
    """Robustly extracts and parses JSON array of facts from Nemotron Nano output.

    Handles stray reasoning tags (<think>...</think>), preamble text, markdown code blocks,
    trailing commas, and wrapped objects (e.g. {"facts": [...]}).
    """
    if not raw:
        return []

    # 1. Strip reasoning blocks
    text = clean_reasoning_text(raw)

    # 2. Try direct parse first
    text_stripped = text.strip()
    try:
        data = json.loads(text_stripped)
        if isinstance(data, list):
            return data
        if isinstance(data, dict):
            for k in ("facts", "extracted_facts", "memories", "items", "data"):
                if isinstance(data.get(k), list):
                    return data[k]
    except Exception:
        pass

    # 3. Extract from markdown code fences: ```json ... ``` or ``` ... ```
    fence_match = re.search(r"```(?:json)?\s*([\s\S]*?)\s*```", text, flags=re.IGNORECASE)
    if fence_match:
        fence_content = fence_match.group(1).strip()
        try:
            data = json.loads(fence_content)
            if isinstance(data, list):
                return data
            if isinstance(data, dict):
                for k in ("facts", "extracted_facts", "memories", "items", "data"):
                    if isinstance(data.get(k), list):
                        return data[k]
        except Exception:
            text = fence_content

    # 4. Find the outer JSON array [ ... ] in text using brackets
    start_idx = text.find("[")
    end_idx = text.rfind("]")
    if start_idx != -1 and end_idx > start_idx:
        array_str = text[start_idx : end_idx + 1].strip()
        try:
            data = json.loads(array_str)
            if isinstance(data, list):
                return data
        except Exception:
            cleaned_array = re.sub(r",\s*([\]}])", r"\1", array_str)
            try:
                data = json.loads(cleaned_array)
                if isinstance(data, list):
                    return data
            except Exception:
                pass

    # 5. Find a JSON object { ... } if array wasn't found
    start_obj = text.find("{")
    end_obj = text.rfind("}")
    if start_obj != -1 and end_obj > start_obj:
        obj_str = text[start_obj : end_obj + 1].strip()
        try:
            data = json.loads(obj_str)
            if isinstance(data, dict):
                for k in ("facts", "extracted_facts", "memories", "items", "data"):
                    if isinstance(data.get(k), list):
                        return data[k]
        except Exception:
            cleaned_obj = re.sub(r",\s*([\]}])", r"\1", obj_str)
            try:
                data = json.loads(cleaned_obj)
                if isinstance(data, dict):
                    for k in ("facts", "extracted_facts", "memories", "items", "data"):
                        if isinstance(data.get(k), list):
                            return data[k]
            except Exception:
                pass

    logger.warning("Could not parse structured JSON from Nano response.")
    return []


class NemotronClient:
    def __init__(self):
        self.model = settings.NEMOTRON_CHAT_MODEL
        self.extract_model = settings.NEMOTRON_EXTRACT_MODEL

    @property
    def base_url(self) -> str:
        """Dynamically resolves the correct endpoint based on key prefix."""
        return settings.resolve_base_url(check_override=True)

    def _score_relevance(self, query: str, mem: MemoryReceipt) -> float:
        """
        Ranks memories by lexical relevance weighted by confidence and staleness penalty.
        We prioritize high-confidence, low-staleness memories in the context window.
        """
        q_words = set(w.lower() for w in re.findall(r"\w+", query) if len(w) > 2)
        if not q_words:
            return mem.current_confidence

        text_corpus = f"{mem.content} {mem.source_title} {mem.source_excerpt} {mem.category}".lower()
        matched = sum(1 for w in q_words if w in text_corpus)
        relevance_ratio = matched / len(q_words)

        # Staleness weight: fresh = 1.0, decaying = 0.75, stale = 0.20
        freshness_weight = 1.0
        if mem.status == "decaying":
            freshness_weight = 0.75
        elif mem.status == "stale":
            freshness_weight = 0.20

        return (relevance_ratio * 0.6 + mem.current_confidence * 0.4) * freshness_weight

    def filter_context(
        self,
        query: str,
        memories: List[MemoryReceipt],
        max_receipts: int = 4,
        include_stale: bool = False,
    ) -> List[MemoryReceipt]:
        """
        Minimal context filter: the cloud model only receives the minimal context needed
        to answer a query, never the full vault. Stale memories are filtered out by default.
        """
        candidates = memories if include_stale else [m for m in memories if m.status != "stale"]
        scored = [(m, self._score_relevance(query, m)) for m in candidates]
        scored = [item for item in scored if item[1] > 0.05]
        scored.sort(key=lambda x: x[1], reverse=True)
        return [item[0] for item in scored[:max_receipts]]

    def _build_system_prompt(self, receipts: List[MemoryReceipt]) -> str:
        if not receipts:
            return (
                "You are 'Receipts', a sovereign personal assistant. You currently have no matching "
                "memory receipts in the local vault for this query. Politely state what you know or do not know, "
                "and mention that no verified local memory receipts matched."
            )

        receipts_formatted = []
        for r in receipts:
            receipts_formatted.append(
                f"[Receipt #{r.id}]\n"
                f"  - Fact: {r.content}\n"
                f"  - Category: {r.category} | Freshness: {r.status.upper()} (Confidence: {int(r.current_confidence * 100)}%)\n"
                f"  - Provenance Source: {r.source_title} ({r.source_type})\n"
                f"  - Literal Excerpt: \"{r.source_excerpt}\"\n"
                f"  - Last Confirmed: {r.last_confirmed_at[:10]}"
            )

        context_block = "\n\n".join(receipts_formatted)
        return (
            "You are 'Receipts', a sovereign personal AI companion powered by NVIDIA Nemotron on Nebius Token Factory.\n"
            "You have access to a local-first memory vault. Answer the user's query using ONLY the verified memory receipts below.\n"
            "RULES:\n"
            "1. Always explicitly cite the exact receipt ID in brackets whenever you use a fact, e.g., '[Receipt #REC-ASYNC1]'.\n"
            "2. If multiple receipts apply, cite each relevant receipt.\n"
            "3. If a memory was corrected, adhere strictly to the latest fact state.\n"
            "4. Be direct, helpful, and concise. Never hallucinate facts not substantiated by a receipt.\n\n"
            f"<VERIFIED_MEMORY_RECEIPTS>\n{context_block}\n</VERIFIED_MEMORY_RECEIPTS>"
        )

    async def _call_nebius(
        self,
        system_prompt: str,
        user_message: str,
        model: Optional[str] = None,
        max_tokens: int = 600,
        temperature: float = 0.2,
        fallback_model: Optional[str] = None,
    ) -> ModelCallResult:
        """
        Authenticated call to Nebius Token Factory with bounded retries and fallback.
        429/5xx/timeouts retry with exponential backoff, then try the configured fallback.
        Other 4xx errors fail immediately without logging response bodies or credentials.
        - Raises ValueError if no API key is configured.
        """
        api_key = settings.NEBIUS_API_KEY
        if not api_key or api_key in ("mock", "your_nebius_api_key_here") or len(api_key) < 10:
            raise ValueError(
                "NEBIUS_API_KEY is not set or is a placeholder. "
                "Get a Nebius Token Factory key and set NEBIUS_API_KEY."
            )

        endpoint_base = self.base_url
        target_model = model or self.model
        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        candidates = [target_model]
        if fallback_model and fallback_model != target_model:
            candidates.append(fallback_model)
        if "integrate.api.nvidia.com" in endpoint_base:
            for nim_model in ("nvidia/nemotron-3.5-bolt-e4b", "nvidia/nemotron-3-nano-omni-30b-a3b-reasoning"):
                if nim_model not in candidates:
                    candidates.append(nim_model)
        last_error: Optional[Exception] = None
        for model_index, candidate in enumerate(candidates):
            payload = {
                "model": candidate,
                "messages": [
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_message},
                ],
                "temperature": temperature,
                "max_tokens": max_tokens,
            }
            retryable_failure = False
            for attempt in range(_MAX_RETRIES + 1):
                request_id = vault.record_outbound_request(
                    candidate,
                    f"{endpoint_base}/chat/completions",
                    payload,
                )
                request_started = perf_counter()
                try:
                    async with httpx.AsyncClient(timeout=45.0) as client:
                        resp = await client.post(
                            f"{endpoint_base}/chat/completions", headers=headers, json=payload
                        )
                    if resp.status_code == 200:
                        data = resp.json()
                        msg = data["choices"][0]["message"]
                        content = msg.get("content") or msg.get("reasoning_content") or ""
                        latency_ms = round((perf_counter() - request_started) * 1000)
                        vault.update_outbound_request(request_id, "success", latency_ms)
                        usage = data.get("usage") or {}
                        degraded = (
                            f"Primary model unavailable; answered with configured fallback model {candidate}."
                            if model_index else None
                        )
                        return ModelCallResult(
                            text=content,
                            model=candidate,
                            degraded_message=degraded,
                            latency_ms=latency_ms,
                            input_tokens=usage.get("prompt_tokens"),
                            output_tokens=usage.get("completion_tokens"),
                        )
                    if resp.status_code == 429 or resp.status_code >= 500:
                        latency_ms = round((perf_counter() - request_started) * 1000)
                        vault.update_outbound_request(request_id, f"http_{resp.status_code}", latency_ms)
                        retryable_failure = True
                        last_error = RuntimeError(f"Token Factory returned HTTP {resp.status_code} for the configured model.")
                    else:
                        latency_ms = round((perf_counter() - request_started) * 1000)
                        vault.update_outbound_request(request_id, f"http_{resp.status_code}", latency_ms)
                        raise RuntimeError(
                            f"Token Factory returned HTTP {resp.status_code} for configured model {candidate}."
                        )
                except (httpx.TimeoutException, httpx.ConnectError) as net_err:
                    latency_ms = round((perf_counter() - request_started) * 1000)
                    vault.update_outbound_request(request_id, type(net_err).__name__, latency_ms)
                    retryable_failure = True
                    last_error = RuntimeError(f"Token Factory network request failed: {type(net_err).__name__}.")

                if attempt < _MAX_RETRIES and retryable_failure:
                    wait = _RETRY_BACKOFF * (2 ** attempt)
                    logger.warning("Retrying Token Factory request in %.1fs (attempt %d/%d).", wait, attempt + 1, _MAX_RETRIES)
                    await asyncio.sleep(wait)
                elif not retryable_failure:
                    break
            if model_index == 0 and len(candidates) > 1 and retryable_failure:
                logger.warning("Primary model retries exhausted; trying configured fallback model.")
                continue
            if retryable_failure:
                break
        raise last_error or RuntimeError(f"Token Factory request failed for configured model {target_model}.")

    async def list_available_models(self) -> List[str]:
        """List model IDs from the documented Nebius Token Factory models API."""
        if not settings.NEBIUS_API_KEY or len(settings.NEBIUS_API_KEY) < 10:
            raise ValueError("Configure NEBIUS_API_KEY before listing Token Factory models.")
        async with httpx.AsyncClient(timeout=15.0) as client:
            response = await client.get(
                f"{self.base_url}/models",
                headers={"Authorization": f"Bearer {settings.NEBIUS_API_KEY}"},
            )
        if response.status_code != 200:
            raise RuntimeError(f"Token Factory model list returned HTTP {response.status_code}.")
        data = response.json().get("data", [])
        return sorted({item["id"] for item in data if isinstance(item, dict) and isinstance(item.get("id"), str)})

    async def answer_query(
        self,
        query: str,
        all_memories: List[MemoryReceipt],
        include_stale: bool = False,
        max_receipts: int = 4,
    ) -> QueryResponse:
        filtered_receipts = self.filter_context(
            query, all_memories, max_receipts=max_receipts, include_stale=include_stale
        )
        system_prompt = self._build_system_prompt(filtered_receipts)

        # ── Attempt live Nemotron call ─────────────────────────────────────────
        try:
            call_result = await self._call_nebius(
                system_prompt=system_prompt,
                user_message=query,
                model=self.model,
                max_tokens=600,
                fallback_model=settings.NEMOTRON_FALLBACK_MODEL,
            )
            raw_answer = call_result.text
            # Clean stray reasoning text (<think>...</think> / <thought>...</thought>)
            clean_answer = clean_reasoning_text(raw_answer)
            used = self._extract_used_receipts(clean_answer, filtered_receipts)
            logger.info(
                "Nemotron answered query via %s (model=%s, receipts=%d used)",
                self.base_url,
                call_result.model,
                len(used),
            )
            return QueryResponse(
                answer=clean_answer,
                used_receipts=used or filtered_receipts,
                total_vault_memories=len(all_memories),
                context_filtered_count=len(filtered_receipts),
                model_used=f"NVIDIA Nemotron ({call_result.model}) via Nebius Token Factory",
                is_simulated=False,
                degraded_message=call_result.degraded_message,
                latency_ms=call_result.latency_ms,
                input_tokens=call_result.input_tokens,
                output_tokens=call_result.output_tokens,
                reasoning_steps=[
                    f"Selected {len(filtered_receipts)} receipt(s) using query relevance and freshness.",
                    "Stale receipts were excluded by default." if not include_stale else "Stale receipts were included by user choice.",
                    f"Answer references {len(used)} receipt(s).",
                ],
            )

        except ValueError as key_err:
            # No / invalid API key
            logger.warning("Live Nemotron unavailable: %s", key_err)
            if settings.STRICT_LIVE_MODE:
                raise  # Bubble up so FastAPI returns 503
            logger.warning("Falling back to simulation mode (STRICT_LIVE_MODE=False).")

        except RuntimeError as api_err:
            # Real API failure with full diagnostics in the error
            logger.error(
                "Nebius/NVIDIA API call FAILED (model=%s, endpoint=%s):\n%s",
                self.model,
                self.base_url,
                api_err,
                exc_info=True,
            )
            if settings.STRICT_LIVE_MODE:
                raise  # Bubble up so FastAPI returns 503 with the diagnostic message
            logger.warning("Falling back to simulation mode (STRICT_LIVE_MODE=False).")

        # ── Simulation fallback (only when STRICT_LIVE_MODE=False) ────────────
        simulated_answer, used = self._simulate_nemotron_response(query, filtered_receipts)
        simulated_answer_with_banner = simulated_answer + _SIMULATED_BANNER

        return QueryResponse(
            answer=simulated_answer_with_banner,
            used_receipts=used,
            total_vault_memories=len(all_memories),
            context_filtered_count=len(filtered_receipts),
            model_used=f"NVIDIA Nemotron ({self.model}) [SIMULATED — no live API key]",
            is_simulated=True,
            reasoning_steps=[
                f"Selected {len(filtered_receipts)} receipt(s) using local keyword matching.",
                "No provider request was made for this simulated answer.",
            ],
        )

    def _extract_used_receipts(
        self, answer: str, candidates: List[MemoryReceipt]
    ) -> List[MemoryReceipt]:
        matched = [r for r in candidates if r.id in answer]
        return matched if matched else candidates

    # ─── Nemotron Nano: post-chat fact extraction ──────────────────────────────

    async def extract_facts_from_turn(
        self,
        user_message: str,
        assistant_answer: str,
        existing_receipt_ids: List[str],
    ) -> List[Dict[str, Any]]:
        """
        Calls the configured Nemotron Nano model on Nebius Token Factory to extract durable facts from the
        latest chat turn, each with a source excerpt taken verbatim from the conversation.

        Returns a list of candidate dicts suitable for creating MemoryCreateRequest objects.
        Returns an empty list (and logs a warning) if the API key is absent or the call fails.
        """
        system_prompt = (
            "You are a fact-extraction assistant. "
            "Given a user message and an assistant reply, identify any durable, personal facts "
            "that would be worth storing in a sovereign memory vault. "
            "Output ONLY a JSON array (no prose, no markdown fences). "
            "Each element must have these exact keys:\n"
            "  content      – concise fact statement (max 200 chars)\n"
            "  category     – one of: preference, active_project, factual_web, personal\n"
            "  decay_curve  – one of: lifestyle_preference, active_project, transient_state\n"
            "  source_excerpt – the exact verbatim sentence(s) from the conversation that prove this fact (max 300 chars)\n"
            "  confidence   – float 0.0–1.0 (your estimate of how reliable this is)\n"
            "If there are no new durable facts, output an empty array: []\n"
            "Do not repeat facts that are already captured (existing IDs will be listed)."
        )
        user_message_for_nano = (
            f"EXISTING RECEIPT IDs (do not repeat these facts): {existing_receipt_ids}\n\n"
            f"USER SAID:\n{user_message}\n\n"
            f"ASSISTANT REPLIED:\n{assistant_answer}"
        )

        try:
            call_result = await self._call_nebius(
                system_prompt=system_prompt,
                user_message=user_message_for_nano,
                model=self.extract_model,
                max_tokens=800,
                temperature=0.1,
                fallback_model=self.model,
            )
            facts = parse_nano_json(call_result.text)
            return facts

        except ValueError as key_err:
            logger.warning("Nano extraction skipped (no API key): %s", key_err)
            return []
        except json.JSONDecodeError as jde:
            logger.error("Nano returned invalid JSON — skipping extraction: %s", jde)
            return []
        except Exception as exc:
            logger.error(
                "Nemotron Nano extraction FAILED (model=%s): %s",
                self.extract_model,
                exc,
                exc_info=True,
            )
            return []

    async def generate_memory_suggestions(
        self,
        memories: List[MemoryReceipt],
        user_context: str = "",
    ) -> List[Dict[str, Any]]:
        """
        Agentic tool: asks Nemotron to analyze the vault and suggest:
        - Which memories should be refreshed (decaying/stale)
        - What follow-up questions to ask the user
        - Potential relationship clusters (memory graph hints)
        Returns list of suggestion dicts.
        """
        if not memories:
            return []

        vault_summary = "\n".join([
            f"[{m.id}] {m.status.upper()} ({int(m.current_confidence*100)}%): {m.content[:120]}"
            for m in memories[:20]
        ])

        system_prompt = (
            "You are an agentic memory analyst assistant. "
            "Analyze the user's sovereign memory vault and return a JSON array of actionable suggestions. "
            "Each suggestion must have:\n"
            "  type: one of 'refresh_alert', 'conflict_hint', 'graph_cluster', 'ask_user'\n"
            "  priority: 'high', 'medium', or 'low'\n"
            "  receipt_ids: list of relevant receipt IDs (can be empty)\n"
            "  title: short title (max 60 chars)\n"
            "  description: explanation (max 200 chars)\n"
            "  action: suggested action for the user\n"
            "Return ONLY the JSON array, no prose."
        )
        user_msg = (
            f"VAULT SNAPSHOT (most recent 20 memories):\n{vault_summary}\n\n"
            f"USER CONTEXT: {user_context or 'No additional context provided.'}\n\n"
            "Identify the top 3-5 most actionable insights, focusing on:\n"
            "1. Memories approaching staleness that the user should reaffirm\n"
            "2. Potential contradictions or preference shifts worth resolving\n"
            "3. Semantic clusters that form a useful memory graph relationship\n"
            "4. Important follow-up questions to strengthen provenance"
        )

        try:
            call_result = await self._call_nebius(
                system_prompt=system_prompt,
                user_message=user_msg,
                model=self.model,
                max_tokens=1000,
                temperature=0.3,
                fallback_model=settings.NEMOTRON_FALLBACK_MODEL,
            )
            raw_cleaned = clean_reasoning_text(call_result.text)
            suggestions = parse_nano_json(raw_cleaned)
            if not isinstance(suggestions, list):
                return []
            return suggestions[:6]
        except Exception as exc:
            logger.error("Agent suggestions failed: %s", exc)
            return []

    # ─── Simulated fallback (keyword if/else) — clearly labelled ─────────────

    def _simulate_nemotron_response(
        self, query: str, receipts: List[MemoryReceipt]
    ) -> Tuple[str, List[MemoryReceipt]]:
        """Local keyword-matching fallback used when no Nebius API key is set.

        This is NOT Nemotron inference. The banner appended by answer_query
        makes that explicit to the user. Only active when STRICT_LIVE_MODE=False.
        """
        if not receipts:
            return (
                "I searched your local memory vault, but found no verified memory receipts matching your query. "
                "Because Receipts is sovereign and local-first, I will not guess or extrapolate without a receipt in your vault.",
                [],
            )

        q_lower = query.lower()
        used = []

        # Planning / Communication
        if any(w in q_lower for w in ["sprint", "meeting", "planning", "async", "schedule", "standup", "communication"]):
            pref_receipts = [r for r in receipts if "REC-ASYNC1" in r.id or "preference" in r.category]
            proj_receipts = [r for r in receipts if "REC-RUST2" in r.id or "project" in r.category]

            answer_parts = []
            if pref_receipts:
                r = pref_receipts[0]
                used.append(r)
                answer_parts.append(
                    f"Based on your sovereign memory receipt [Receipt #{r.id}], {r.content} "
                    f"(Source: *{r.source_title}*, confidence {int(r.current_confidence * 100)}%)."
                )
            if proj_receipts and any(w in q_lower for w in ["sprint", "goal", "work", "focus"]):
                r = proj_receipts[0]
                used.append(r)
                answer_parts.append(
                    f"Additionally, your current sprint focus is: {r.content} [Receipt #{r.id}]."
                )
            if not answer_parts:
                primary = receipts[0]
                used.append(primary)
                answer_parts.append(f"According to your records [Receipt #{primary.id}], {primary.content}")
            return (" ".join(answer_parts), used)

        # Tech / Nebius / Nemotron
        if any(w in q_lower for w in ["nebius", "nemotron", "nvidia", "model", "token factory", "ai"]):
            nemo_r = [r for r in receipts if "NEMO" in r.id or "nebius" in r.content.lower()]
            if nemo_r:
                r = nemo_r[0]
                used.append(r)
                return (
                    f"According to your web intelligence receipt [Receipt #{r.id}], {r.content} "
                    f"This was sourced from *{r.source_title}* with {int(r.current_confidence * 100)}% verified confidence.",
                    used,
                )

        # Dietary / Coffee
        if any(w in q_lower for w in ["coffee", "latte", "drink", "diet", "milk", "order"]):
            coffee_r = [r for r in receipts if "COFFEE" in r.id or "dietary" in r.content.lower() or "latte" in r.content.lower()]
            if coffee_r:
                r = coffee_r[0]
                used.append(r)
                return (
                    f"According to your preference receipt [Receipt #{r.id}], {r.content} "
                    f"(Verified from {r.source_title}).",
                    used,
                )

        # Location / Contact
        if any(w in q_lower for w in ["location", "live", "seattle", "pst", "time", "timezone", "city",
                                      "roaming", "phone", "number", "contact", "sim"]):
            loc_r = [r for r in receipts if "PST" in r.id or "seattle" in r.content.lower()
                     or "roaming" in r.content.lower() or "phone" in r.content.lower()
                     or "pst" in r.content.lower()]
            if loc_r:
                r = loc_r[0]
                used.append(r)
                return (
                    f"Your personal records indicate: {r.content} [Receipt #{r.id}] "
                    f"(Confidence: {int(r.current_confidence * 100)}%, Status: {r.status.upper()}).",
                    used,
                )

        # General fallback
        q_words = set(w.lower() for w in re.findall(r"\w+", query) if len(w) > 2)
        if q_words:
            best_overlap = max(
                sum(1 for w in q_words if w in f"{r.content} {r.source_title} {r.category}".lower()) / len(q_words)
                for r in receipts
            )
            if best_overlap < 0.25:
                return (
                    "I searched your local memory vault, but found no verified memory receipts matching your query. "
                    "Because Receipts is sovereign and local-first, I will not guess or extrapolate without a receipt in your vault.",
                    [],
                )

        primary = receipts[0]
        used.append(primary)
        return (
            f"According to [Receipt #{primary.id}] ({primary.source_title}): {primary.content} "
            f"[Freshness: {primary.status.upper()}, Confidence: {int(primary.current_confidence * 100)}%].",
            used,
        )


